// tweak these params for fun

// fog
const float fogBottom = 0.;
const float fogTop = 15.;

// camera
const float fisheyeWidth = .8;

// material
const float primShininess = .8;
const vec3 primColour = vec3(0);

// landscape
const float lacunarity = 2.;
const float omega = 2.;
const float scaleXZ = 35.;
const float scaleY = 6.;


// uncomment different prim types in here
float Prim( vec3 pos, vec3 origin, float gridSize )
{
    pos -= origin;

    vec2 angles = origin.xy*.3 + sin(vec2(.3,.17)*iTime)*2.;
    pos.xy = pos.xy*cos(angles.x)+sin(angles.x)*vec2(-1,1)*pos.yx;
    pos.yz = pos.yz*cos(angles.y)+sin(angles.y)*vec2(-1,1)*pos.zy;

    // spheres
//    return length(pos)-.6*gridSize;

    // cubes
//    float r = .05*gridSize; pos = max(abs(pos)-gridSize*.4+r,0.); return length(pos)-r;

    // elongated cubes
    float r = .05*gridSize; pos = max(abs(pos)-gridSize*vec3(.25,.6,.25)+r,0.); return length(pos)-r;

    // squares
//    float r = .05*gridSize; pos = max(abs(pos)-gridSize*vec3(.5,.05,.5)+r,0.); return length(pos)-r;

    // capsules
//    float r = .25*gridSize; pos = max(abs(pos)-gridSize*vec3(.25,.7,.25)+r,0.); return length(pos)-r;

    // donuts!
//    return length(vec2(length(pos.xz)-.4*gridSize,pos.y))-.2*gridSize;
}



float LandHeight( vec2 posXZ )
{
    // ridged multifractal
    float h = 0.;
    vec2 uv = posXZ/(256.*scaleXZ);
    for ( int i=0; i < 8; i++ )
    {
        uv = -uv*sqrt(3./4.) + uv.yx*sqrt(1./4.)*vec2(-1,1); // rotate so grid is less obvious

        float tap = texture( iChannel0, uv ).x;

        h += mix(1.,h*2.,.5)*(1.-abs(2.*tap-1.)) * pow(omega,-float(i));
        uv *= lacunarity;
    }

    return h*scaleY;
}

float SDF( vec3 pos )
{
//    return (pos.y - LandHeight(pos.xz))*.7;

    float gridSize = .3;
    vec2 gridUV = pos.xz/gridSize;
    vec2 gridFract = fract(gridUV);
    vec2 primGrid = floor(gridUV)*gridSize;

    vec2 d = vec2(0,gridSize);
    vec4 primHeights =
        vec4(
            LandHeight(primGrid+d.xx),
            LandHeight(primGrid+d.yx),
            LandHeight(primGrid+d.xy),
            LandHeight(primGrid+d.yy)
        );

    return .8*min(min(min(
            Prim(pos, vec3(primGrid+d.xx,primHeights.x).xzy, gridSize), // I really should just switch to z is up
            Prim(pos, vec3(primGrid+d.yx,primHeights.y).xzy, gridSize)),            
            Prim(pos, vec3(primGrid+d.xy,primHeights.z).xzy, gridSize)),            
            Prim(pos, vec3(primGrid+d.yy,primHeights.w).xzy, gridSize));
}


vec3 CameraPath( float t )
{
    return t*vec3(.1,0,2) + vec3(sin(t/3.)*4.,0,0);
}


// returns rgb and distance to intersection
vec4 Trace( out float fogVisibility, in vec3 pos, in vec3 ray )
{
    float t = 0.;
    for ( int i=0; i < 500; i++ )
    {
        float h = SDF(pos+t*ray);
        t += h;
        if ( h < .01 || t > 1000. ) break;
    }

    vec3 col = vec3(0);
    if ( t > 1000. ) col = vec3(0,.05,.2);

    // hard-edged fog layer
    // I wrote this so it would give a nice sky gradient
    // but it also looks really cool spanning a shorter area
    float fogStart = 0.;
    float fogEnd = t;
    if ( pos.y > fogTop ) { if ( ray.y >= 0. ) fogEnd=fogStart; else fogStart = (fogTop-pos.y)/ray.y; }
    else if ( pos.y < fogBottom ) { if ( ray.y <= 0. ) fogEnd=fogStart; else fogStart = (fogBottom-pos.y)/ray.y; }
    if ( ray.y > 0. ) fogEnd = min(fogEnd,(fogTop-pos.y)/ray.y);
    else if ( ray.y < 0. ) fogEnd = min(fogEnd,(fogBottom-pos.y)/ray.y);

    fogVisibility = exp2(-max(0.,fogEnd-fogStart)/40.);

    col = mix( vec3(.85,1.,1.2), col, fogVisibility );

    return vec4(col,t);
}

void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
//    vec3 ray = normalize(vec3((fragCoord-iResolution.xy*.5)/iResolution.y, .5));
    vec3 ray = vec3(fisheyeWidth*(fragCoord-iResolution.xy*.5)/iResolution.y, 0);
    ray.z = sqrt(1.-dot(ray.xy,ray.xy)); // spherical camera for lols

    ray.yz = ray.yz*cos(.2)+sin(.2)*vec2(-1,1)*ray.zy;
    float yaw = iTime*.1;
    ray.xz = ray.xz*cos(yaw)+sin(yaw)*vec2(-1,1)*ray.zx;
    vec3 pos = CameraPath(iTime);

    // smooth between height samples
    float stepSpacing = 1.5;
    float step0 = floor(iTime/stepSpacing)*stepSpacing;
    float step1 = step0 + stepSpacing;
    pos.y = mix( LandHeight( CameraPath(step0).xz ), LandHeight( CameraPath(step1).xz ), smoothstep(step0,step1,iTime) )
            +1.;

    float fogVisibility = 1.;
    vec4 traced = Trace( fogVisibility, pos, ray );

    if ( traced.w <= 1000. )
    {
        // ray hit something, composite a reflection
        vec2 d = vec2(-1,1)*.01;

        vec3 pos2 = pos+ray*traced.w;
        vec3 normal = normalize(
                        SDF(pos2+d.xxx)*d.xxx+
                        SDF(pos2+d.yyx)*d.yyx+
                        SDF(pos2+d.yxy)*d.yxy+
                        SDF(pos2+d.xyy)*d.xyy
                    );

        vec3 ray2 = reflect(ray,normal);

        float ignore;
        vec4 traced2 = Trace( ignore, pos2+ray2*.2, ray2 ); //.2 kick starts the ray 'cause i know we're on a concave surface

        vec3 reflection = traced2.rgb;
        vec3 diffuse = primColour * mix( .1, 1., max(dot(normal,normalize(vec3(0,5,3))),0.) );
        vec3 col = mix( diffuse, reflection, mix(primShininess,1.,pow(1.+dot(normal,ray),5.)) );

        // copper
//        vec3 col = reflection * mix( vec3(.6,.2,.1), vec3(1), pow(1.+dot(normal,ray),5.) );

        // note spheres are currently black so we can just do this additively
        traced.rgb += col*fogVisibility;
    }

    fragColour = vec4( pow( traced.rgb, vec3(1./2.2) ), 1. );
}
